// ONE observer · single-file build for the Cloudflare dashboard editor · generated by tools/bundle.js
// Paste the whole file into a Worker (Workers & Pages → your worker → Edit code), then add the WITNESS KV binding and variables.
// ONE rows SDK · v0.1
// The row calculus of WP-03 "The Handshake as a Program" in runnable form.
// Zero dependencies. Runs in Cloudflare Workers, Node 20+, and browsers (WebCrypto only).
//
// A program is (schema, manifest, rows). Rows are hashed into a transcript T.
// A key exists only if every row verifies; otherwise the program halts with a
// signed refusal naming the failed row. Nothing here invents cryptography:
// SHA-256, HKDF-SHA256, HMAC, Ed25519 (WebCrypto). ONE's own constructions are not in this file.

const SCHEMA = 1;
const te = new TextEncoder();

// ---------- canonical encoding (prefix-free, injective) ----------
function field(s) {
  const b = te.encode(String(s ?? ""));
  const out = new Uint8Array(4 + b.length);
  new DataView(out.buffer).setUint32(0, b.length);
  out.set(b, 4);
  return out;
}
function cat(...parts) {
  const n = parts.reduce((a, p) => a + p.length, 0);
  const out = new Uint8Array(n);
  let o = 0;
  for (const p of parts) { out.set(p, o); o += p.length; }
  return out;
}
function encodeRow(r) {
  return cat(field(r.type), field(r.claim), field(r.evidence), field(r.cls || "S"), field(r.fail || "refuse"));
}
function encodeManifest(m) {
  return cat(field("manifest"), field(m.version), field(JSON.stringify(m.anchors || {})), field(JSON.stringify(m.term || {})));
}

// ---------- hashing, derivation ----------
async function sha256(bytes) {
  return new Uint8Array(await crypto.subtle.digest("SHA-256", bytes));
}
const hex = (u8) => [...u8].map((b) => b.toString(16).padStart(2, "0")).join("");
const fromHex = (h) => new Uint8Array(h.match(/../g).map((x) => parseInt(x, 16)));

// T0 = H(enc(schema) || enc(manifest)); Ti = H(T(i-1) || enc(row_i)); T = Tn   (WP-03 Appendix A)
async function transcript(program) {
  let T = await sha256(cat(field("schema:" + program.schema), encodeManifest(program.manifest)));
  for (const r of program.rows) T = await sha256(cat(T, encodeRow(r)));
  return hex(T);
}

// k = KDF(ss, "one/key" || label || T)   (WP-03 Definition 7 and 14)
async function derive(ssHex, T, label = "one/key") {
  const key = await crypto.subtle.importKey("raw", fromHex(ssHex), "HKDF", false, ["deriveBits"]);
  const bits = await crypto.subtle.deriveBits({ name: "HKDF", hash: "SHA-256", salt: new Uint8Array(0), info: te.encode(label + "\u0000" + T) }, key, 256);
  return hex(new Uint8Array(bits));
}
async function subkeys(ssHex, T) {
  const out = {};
  for (const l of ["one/key", "enc", "mac", "wit", "rot"]) out[l] = await derive(ssHex, T, l);
  return out;
}

// ---------- programs ----------
function program(manifest, rows, schema = SCHEMA) {
  return { schema, manifest, rows: [{ type: "manifest", claim: "v" + manifest.version, evidence: "signed by quorum", cls: "S", fail: "refuse" }, ...rows] };
}
function wellFormed(p) {
  if (!p.rows.length || p.rows[0].type !== "manifest") return { ok: false, why: "first row must be the manifest" };
  const seen = new Set();
  for (const r of p.rows) {
    const k = r.type + "\u0000" + r.claim;
    if (seen.has(k)) return { ok: false, why: "duplicate row " + r.type };
    seen.add(k);
  }
  const epochAt = p.rows.findIndex((r) => r.type === "epoch");
  for (let i = 0; i < p.rows.length; i++) if (p.rows[i].cls === "F" && (epochAt < 0 || epochAt > i)) return { ok: false, why: "fresh row " + p.rows[i].type + " before epoch row" };
  return { ok: true };
}

// Evaluate: verifiers[type](row, ctx) -> boolean | Promise<boolean>. Local verifiers only (independence).
// Returns the FIRST failing row (min i), as the operational semantics require.
async function evaluate(p, verifiers = {}, ctx = {}) {
  const wf = wellFormed(p);
  if (!wf.ok) return { ok: false, index: -1, row: null, why: "malformed: " + wf.why };
  for (let i = 0; i < p.rows.length; i++) {
    const r = p.rows[i];
    const v = verifiers[r.type] || defaultVerifier;
    let ok = false;
    try { ok = await v(r, ctx); } catch { ok = false; }
    if (!ok) return { ok: false, index: i, row: r, why: r.type + " failed" };
  }
  return { ok: true, index: -1, row: null };
}
const defaultVerifier = (r) => r.claim !== "unresolved" && r.evidence !== "";

// Acceptance is a conjunction, so adding a row can only restrict (Theorem 3).
function extend(p, row) { return { ...p, rows: [...p.rows, row] }; }

// Delegation: Π′ must contain every row of Π in order, plus a delegation row. Anything else is malformed (Definition 9).
function narrows(base, delegated) {
  let j = 0;
  for (const r of delegated.rows) if (j < base.rows.length && r.type === base.rows[j].type && r.claim === base.rows[j].claim) j++;
  return j === base.rows.length && delegated.rows.some((r) => r.type === "delegation");
}
async function delegate(base, extraRows, delegator) {
  const T = await transcript(base);
  const row = { type: "delegation", claim: "delegate:" + delegator, evidence: "sig over H(T(" + T.slice(0, 12) + "))", cls: "S", fail: "malformed" };
  return { ...base, rows: [...base.rows, row, ...extraRows] };
}

// ---------- witnesses (outside verifiers: Ed25519; inside a relationship the SDK would use k_wit) ----------
async function witnessKeygen() {
  const k = await crypto.subtle.generateKey({ name: "Ed25519" }, true, ["sign", "verify"]);
  return { privateJwk: await crypto.subtle.exportKey("jwk", k.privateKey), publicJwk: await crypto.subtle.exportKey("jwk", k.publicKey) };
}
function witnessPayload(T, verdict, epoch) {
  // H(T) || i* || type || epoch  (Refuse rule); "acc" for accepting runs
  return `one-witness/1\u0000${T}\u0000${verdict.ok ? "acc" : verdict.index}\u0000${verdict.ok ? "" : verdict.row.type}\u0000${epoch}`;
}
async function signWitness(privateJwk, T, verdict, epoch) {
  const key = await crypto.subtle.importKey("jwk", privateJwk, { name: "Ed25519" }, false, ["sign"]);
  const payload = witnessPayload(T, verdict, epoch);
  const sig = new Uint8Array(await crypto.subtle.sign({ name: "Ed25519" }, key, te.encode(payload)));
  return { payload, sig: hex(sig) };
}
async function verifyWitness(publicJwk, w) {
  const key = await crypto.subtle.importKey("jwk", { kty: "OKP", crv: "Ed25519", x: publicJwk.x }, { name: "Ed25519" }, false, ["verify"]);
  return crypto.subtle.verify({ name: "Ed25519" }, key, fromHex(w.sig), te.encode(w.payload));
}

// ---------- compiler (heuristic; the production compiler resolves against the estate) ----------
function compile(sentence, manifest, ctx = {}) {
  const t = sentence.toLowerCase();
  const rows = [];
  const add = (type, claim, evidence, cls = "S", span = null, fail = "refuse") => rows.push({ type, claim, evidence, cls, span, fail });
  add("epoch", String(ctx.epoch ?? Math.floor(Date.now() / 60000)), "beacon or worker clock");
  const ag = t.match(/the ([a-z\- ]+?) agent/);
  if (ag) add("identity", ag[1].trim().replace(/ /g, "-") + "-agent", "signature or credential", "S", ag[0]);
  else if (/registered agent|human/.test(t)) add("identity", "human or registered agent", "presence token or RFC 9421 signature", "S", t.match(/human|registered agent/)[0]);
  else if (/only i|owner/.test(t)) add("identity", "owner", "this account", "S", t.match(/only i|owner/)[0]);
  else add("identity", "unresolved", "", "S");
  const purp = ["servicing", "diligence", "advisory", "review", "read", "analyze", "browse", "stated purpose", "appraise", "checkout"].find((p) => t.includes(p));
  if (purp) add("purpose", purp, "enters key derivation", "S", purp); else add("purpose", "unresolved", "", "S");
  const pol = [];
  if (/no export|never export/.test(t)) pol.push("export=deny");
  if (/observe only/.test(t)) pol.push("mode=observe");
  if (/bot score is evidence|score is evidence/.test(t)) pol.push("score=evidence");
  add("policy", "rev " + (ctx.rev ?? 1) + (pol.length ? " · " + pol.join(" · ") : ""), "signed at compile", "S", [/observe only/.test(t) ? "observe only" : null, /bot score/.test(t) ? "bot score" : null].filter(Boolean));
  if (/attested|company laptop|attested laptop/.test(t)) add("device", "attested", "TPM or App Attest quote", "I", t.match(/attested laptops?|attested devices?|attested/)[0]);
  const reg = t.match(/switzerland|canada|united states|in-region|europe|customer endpoints/);
  if (reg) add("context", reg[0], "edge metadata or residency proof", "S", reg[0]);
  const m = t.match(/(\d+)\s*(minutes|minute|min|hours|hour|hr|days|day)/);
  if (m) add("lifecycle", m[1] + " " + m[2], "epoch comparison", "F", m[0]);
  else if (/sessions?/.test(t)) add("lifecycle", "session", "epoch comparison", "F", "sessions");
  const comp = t.match(/dora|hipaa|gdpr|sox|pci/);
  if (comp) add("compliance", comp[0].toUpperCase(), "regime credential", "S", comp[0]);
  if (/sub-agent|inherit|may only add|delegat/.test(t)) add("delegation", "inherit · may only add", "Π′ ⊒ Π", "S", t.match(/sub-agents? inherit(?: and may only add)?|inherit|delegat[a-z]*/)[0], "malformed");
  const p = program(manifest, rows);
  p.sentence = sentence;
  p.unresolved = rows.filter((r) => r.claim === "unresolved").length;
  return p;
}

// RFC 9421 HTTP Message Signatures · Ed25519 profile as used by Web Bot Auth
// (draft-meunier-webbotauth-httpsig-protocol). Verify on the origin, sign in a demo agent.
// Zero dependencies. Not yet cross-validated against the Cloudflare reference test vectors:
// run tools/agent.js against http-message-signatures-example.research.cloudflare.com/debug to confirm.

const te2 = new TextEncoder();
const WEB_BOT_AUTH_TAG = "web-bot-auth";
const DIRECTORY_PATH = "/.well-known/http-message-signatures-directory";

const b64u = {
  enc: (u8) => btoa(String.fromCharCode(...u8)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, ""),
  dec: (s) => Uint8Array.from(atob(s.replace(/-/g, "+").replace(/_/g, "/").padEnd(Math.ceil(s.length / 4) * 4, "=")), (c) => c.charCodeAt(0)),
};
const b64 = {
  enc: (u8) => btoa(String.fromCharCode(...u8)),
  dec: (s) => Uint8Array.from(atob(s), (c) => c.charCodeAt(0)),
};

// Signature-Input: sig1=("@authority" "@method");created=1;expires=2;keyid="k";alg="ed25519";nonce="n";tag="web-bot-auth"
function parseSignatureInput(h) {
  const m = /^\s*([\w-]+)=\((.*?)\)(.*)$/s.exec(h || "");
  if (!m) return null;
  const [, label, comps, paramStr] = m;
  const components = [...comps.matchAll(/"([^"]+)"/g)].map((x) => x[1]);
  const params = {};
  for (const p of paramStr.split(";").map((s) => s.trim()).filter(Boolean)) {
    const [k, v = ""] = p.split(/=(.*)/s);
    params[k] = /^".*"$/.test(v) ? v.slice(1, -1) : (/^\d+$/.test(v) ? Number(v) : v);
  }
  return { label, components, params, inner: `(${comps})${paramStr}` };
}
function parseSignature(h, label) {
  const m = new RegExp(`(?:^|,)\\s*${label}=:([A-Za-z0-9+/=]+):`).exec(h || "");
  return m ? b64.dec(m[1]) : null;
}
// The Signature-Agent header: either a bare/quoted host or the newer dictionary form.
function parseSignatureAgent(h) {
  if (!h) return null;
  const q = h.match(/"([^"]+)"/);
  const v = (q ? q[1] : h).trim();
  return v.replace(/^https?:\/\//, "").replace(/\/.*$/, "");
}

function componentValue(name, req) {
  const url = new URL(req.url);
  switch (name) {
    case "@authority": return url.host;
    case "@method": return req.method.toUpperCase();
    case "@path": return url.pathname;
    case "@query": return url.search || "?";
    case "@scheme": return url.protocol.replace(":", "");
    case "@target-uri": return url.href;
    default: {
      const v = req.headers.get(name);
      if (v == null) throw new Error("missing covered header " + name);
      return v.trim().replace(/\s+/g, " ");
    }
  }
}
function signatureBase(req, parsed) {
  const lines = parsed.components.map((c) => `"${c}": ${componentValue(c, req)}`);
  lines.push(`"@signature-params": ${parsed.inner}`);
  return lines.join("\n");
}

async function importVerifyKey(jwk) {
  return crypto.subtle.importKey("jwk", { kty: "OKP", crv: "Ed25519", x: jwk.x }, { name: "Ed25519" }, false, ["verify"]);
}
async function jwkThumbprint(jwk) {
  // RFC 7638 for OKP: {"crv","kty","x"} in lexicographic order
  const d = await crypto.subtle.digest("SHA-256", te2.encode(JSON.stringify({ crv: jwk.crv, kty: jwk.kty, x: jwk.x })));
  return b64u.enc(new Uint8Array(d));
}

// verify(req, jwks, {now}) -> { ok, keyid, reason }
async function verifyRequest(req, jwks, opts = {}) {
  const now = opts.now ?? Math.floor(Date.now() / 1000);
  const si = parseSignatureInput(req.headers.get("signature-input"));
  if (!si) return { ok: false, reason: "no Signature-Input" };
  const sig = parseSignature(req.headers.get("signature"), si.label);
  if (!sig) return { ok: false, reason: "no Signature for " + si.label };
  if (si.params.tag && si.params.tag !== WEB_BOT_AUTH_TAG) return { ok: false, reason: "tag " + si.params.tag };
  if (si.params.alg && si.params.alg !== "ed25519") return { ok: false, reason: "alg " + si.params.alg };
  if (si.params.created && si.params.created > now + 300) return { ok: false, reason: "created in the future" };
  if (si.params.expires && si.params.expires < now) return { ok: false, reason: "expired" };
  const keys = (jwks.keys || []).filter((k) => k.kty === "OKP" && k.crv === "Ed25519");
  let jwk = keys.find((k) => k.kid === si.params.keyid);
  if (!jwk && si.params.keyid) for (const k of keys) if ((await jwkThumbprint(k)) === si.params.keyid) jwk = k;
  if (!jwk) jwk = keys[0];
  if (!jwk) return { ok: false, reason: "no Ed25519 key in directory" };
  let base;
  try { base = signatureBase(req, si); } catch (e) { return { ok: false, reason: e.message }; }
  const ok = await crypto.subtle.verify({ name: "Ed25519" }, await importVerifyKey(jwk), sig, te2.encode(base));
  return { ok, keyid: jwk.kid || (await jwkThumbprint(jwk)), reason: ok ? "" : "signature mismatch" };
}

// sign(req, privateJwk, {keyid, components, ttl}) -> { "Signature-Input", "Signature", "Signature-Agent"? }
async function signRequest(req, privateJwk, opts = {}) {
  const components = opts.components || ["@authority"];
  const created = opts.created ?? Math.floor(Date.now() / 1000);
  const expires = created + (opts.ttl ?? 300);
  const keyid = opts.keyid || privateJwk.kid || (await jwkThumbprint(privateJwk));
  const nonce = opts.nonce || b64u.enc(crypto.getRandomValues(new Uint8Array(32)));
  const inner = `(${components.map((c) => `"${c}"`).join(" ")});created=${created};expires=${expires};keyid="${keyid}";alg="ed25519";nonce="${nonce}";tag="${WEB_BOT_AUTH_TAG}"`;
  const parsed = { label: "sig1", components, params: { created, expires, keyid }, inner };
  const key = await crypto.subtle.importKey("jwk", privateJwk, { name: "Ed25519" }, false, ["sign"]);
  const sig = new Uint8Array(await crypto.subtle.sign({ name: "Ed25519" }, key, te2.encode(signatureBase(req, parsed))));
  const h = { "Signature-Input": `sig1=${inner}`, Signature: `sig1=:${b64.enc(sig)}:` };
  if (opts.agent) h["Signature-Agent"] = `"${opts.agent}"`;
  return h;
}

// RFC 9421 Appendix B.1.4 Ed25519 test key. Test only. Never use in production.
const RFC9421_TEST_KEY = {
  kty: "OKP", crv: "Ed25519", kid: "test-key-ed25519",
  x: "JrQLj5P_89iXES9-vFgrIy29clF9CC_oPPsw3c5D0bs",
  d: "n4Ni-HpISpVObnQMW0wOhCKROaIKqKtW_2ZYb2p9KcU",
};

// Verified crawlers: operators that publish the address ranges their bots use.
// A declared crawler (by user agent) whose source address is inside its operator's published list is
// verified against the operator's own statement. Evidence, not inference. Weaker than a signature: shared
// infrastructure and broad ranges. Unknown list, unreachable list, or no match: the request stays unattributed.
// Lists are the operators' published JSON files in the common {"prefixes":[{"ipv4Prefix":..},{"ipv6Prefix":..}]} form.

const DEFAULT_LISTS = {
  "openai.com": ["https://openai.com/gptbot.json", "https://openai.com/chatgpt-user.json", "https://openai.com/searchbot.json"],
  "google.com": [
    "https://developers.google.com/static/search/apis/ipranges/googlebot.json",
    "https://developers.google.com/static/search/apis/ipranges/special-crawlers.json",
    "https://developers.google.com/static/search/apis/ipranges/user-triggered-fetchers.json",
    "https://developers.google.com/static/search/apis/ipranges/user-triggered-fetchers-google.json",
  ],
  "bing.com": ["https://www.bing.com/toolbox/bingbot.json"],
  "perplexity.ai": ["https://www.perplexity.ai/perplexitybot.json", "https://www.perplexity.ai/perplexity-user.json"],
};
// user-agent token -> operator. Order matters: first match wins.
const DECLARATIONS = [
  [/chatgpt-user|gptbot|oai-searchbot|openai/i, "openai.com"],
  [/googlebot|google-inspectiontool|googleother|google-extended|google-cloudvertexbot|googleagent|feedfetcher-google|google-read-aloud|apis-google|gemini/i, "google.com"],
  [/canva/i, "canva.com"],
  [/applebot/i, "apple.com"],
  [/amazonbot/i, "amazon.com"],
  [/duckassistbot|duckduckbot/i, "duckduckgo.com"],
  [/meta-externalagent|meta-externalfetcher|facebookexternalhit/i, "meta.com"],
  [/mistralai/i, "mistral.ai"],
  [/bytespider|tiktokspider/i, "bytedance.com"],
  [/cohere-ai/i, "cohere.com"],
  [/youbot/i, "you.com"],
  [/bingbot|bingpreview/i, "bing.com"],
  [/perplexitybot|perplexity-user/i, "perplexity.ai"],
  [/claudebot|claude-user|claude-searchbot|anthropic/i, "anthropic.com"],
  [/grokbot|xai-grok|grok-deepsearch|xai-searchbot|\bxai\b/i, "x.ai"],   // documented tokens; in practice Grok fetches as a spoofed browser (StackFox, Feb 2026)
  [/applebot/i, "apple.com"],
  [/duckduckbot|yandex|baiduspider|bytespider|ccbot|amazonbot|facebookexternalhit|meta-externalagent|linkedinbot|twitterbot|slackbot|discordbot|telegrambot|whatsapp/i, "other-declared"],
  [/bot\b|crawler|spider|scrapy|python-requests|python-urllib|go-http-client|curl\/|wget\/|httpclient|okhttp|axios|node-fetch|headless/i, "self-declared-automation"],
];
// Forward-confirmed reverse DNS: the operator's own DNS vouches for the address. No list to maintain.
// Suffixes are the documented reverse-DNS domains of each operator's crawlers (configuration; REVERSE_DNS_JSON merges).
const REVERSE_DNS = {
  "google.com": ["googlebot.com", "google.com", "googleusercontent.com"],
  "bing.com": ["search.msn.com"],
  "apple.com": ["applebot.apple.com"],
  "duckduckgo.com": ["duckduckgo.com"],
  "yandex.com": ["yandex.ru", "yandex.net", "yandex.com"],
  "baidu.com": ["baidu.com", "baidu.jp"],
  "meta.com": ["fbsv.net", "facebook.com"],
  "openai.com": ["openai.com"],
  "perplexity.ai": ["perplexity.ai"],
};
function ptrName(ip) {
  if (ip.includes(":")) { const full = expand6(ip); return full.split("").reverse().join(".") + ".ip6.arpa"; }
  return ip.split(".").reverse().join(".") + ".in-addr.arpa";
}
function expand6(ip) {
  const [head, tail] = ip.split("::"); const h = head ? head.split(":") : [], t = tail ? tail.split(":") : [];
  const groups = [...h, ...new Array(8 - h.length - t.length).fill("0"), ...t];
  return groups.map((g) => g.padStart(4, "0")).join("");
}
// dohLookup(name, type) -> array of answer strings; injected so the worker uses DNS-over-HTTPS and tests use a mock.
async function verifyByReverseDns(ip, operator, dohLookup, table = REVERSE_DNS) {
  const suffixes = table[operator]; if (!suffixes || !ip) return { ok: false, method: "reverse dns", reason: "no reverse-dns domains known for operator" };
  let ptrs; try { ptrs = await dohLookup(ptrName(ip), "PTR"); } catch { return { ok: false, method: "reverse dns", reason: "ptr lookup failed" }; }
  const hosts = (ptrs || []).map((h) => h.replace(/\.$/, "").toLowerCase());
  const match = hosts.find((h) => suffixes.some((sfx) => h === sfx || h.endsWith("." + sfx)));
  if (!match) return { ok: false, method: "reverse dns", reason: hosts.length ? `ptr ${hosts[0]} is not under ${operator}'s crawler domains` : "no ptr record" };
  let fwd; try { fwd = await dohLookup(match, ip.includes(":") ? "AAAA" : "A"); } catch { return { ok: false, method: "reverse dns", reason: "forward lookup failed" }; }
  const confirmed = (fwd || []).map((a) => a.toLowerCase()).includes(ip.toLowerCase());
  return confirmed ? { ok: true, method: "forward-confirmed reverse dns", evidence: `${ip} ↔ ${match} (operator's DNS)`, host: match }
                   : { ok: false, method: "reverse dns", reason: `ptr ${match} does not resolve back to ${ip}` };
}
function declares(ua = "", table = DECLARATIONS) {
  for (const [re, op] of table) if (re.test(ua)) return op;
  return null;
}
// Configuration, not code: a JSON array of [pattern, operator] pairs (e.g. from a shared registry) replaces the built-in table.
function declarationsFrom(json) {
  try { const arr = JSON.parse(json); return arr.map(([p, op]) => [new RegExp(p, "i"), op]); } catch { return DECLARATIONS; }
}

// ---- CIDR matching, IPv4 and IPv6 ----
function ipToBigInt(ip) {
  if (ip.includes(":")) {
    const [head, tail = ""] = ip.split("::");
    const h = head ? head.split(":") : [], t = tail ? tail.split(":") : [];
    const parts = [...h, ...Array(8 - h.length - t.length).fill("0"), ...t];
    if (parts.length !== 8) throw new Error("bad ipv6");
    return parts.reduce((acc, p) => (acc << 16n) + BigInt(parseInt(p || "0", 16)), 0n);
  }
  const o = ip.split(".").map(Number);
  if (o.length !== 4 || o.some((x) => !(x >= 0 && x <= 255))) throw new Error("bad ipv4");
  return o.reduce((acc, x) => (acc << 8n) + BigInt(x), 0n);
}
function inCidr(ip, cidr) {
  try {
    const [base, bitsStr] = cidr.split("/");
    const v6 = base.includes(":");
    if (v6 !== ip.includes(":")) return false;
    const total = v6 ? 128n : 32n, bits = BigInt(bitsStr ?? (v6 ? 128 : 32));
    const mask = bits === 0n ? 0n : ((1n << total) - 1n) ^ ((1n << (total - bits)) - 1n);
    return (ipToBigInt(ip) & mask) === (ipToBigInt(base) & mask);
  } catch { return false; }
}
