    if (d.agent !== agentHost) return { ok: false, reason: "delegation is for a different agent" };
    const payload = `one-delegation/1\u0000${d.sid}\u0000${d.T}\u0000${d.agent}\u0000${d.purpose}\u0000${d.exp}`;
