  if (Date.now() - Number(ts) > 86400000) return { ok: false, reason: "app token expired" };
  if ((await hmacHex(env.APP_SHARED_SECRET, appId + "|" + ts)) !== mac) return { ok: false, reason: "app token invalid" };
