    "anthropic.com": { networks: ["396982", "15169"], declared_ranges: false, verification_keys: true, attestation_methods: ["web-bot-auth"] },
    "google.com": { networks: ["15169", "396982"], declared_ranges: true, verification_keys: true, attestation_methods: ["published-ranges", "web-bot-auth"] },
