  if (!consistent.length) return { vocab: networkOwner ? "NETWORK_IDENTITY" : "IDENTITY_UNOBSERVABLE", operator: null, network: networkOwner, residuals: cands.slice(0, 3), reason: "no candidate consistent within tolerance" };
