  const ranked = d.candidates.map((i) => [i, d.x[i]]).sort((a, b) => b[1] - a[1]);
  const best = ranked[0]; const second = ranked[1];
  const verified = E.filter((e) => e.type === "operator" && e.strength === "verified");
  const predicate = (op, provs) => E.some((e) => e.type === "operator" && e.value === op && provs.includes(e.provenance));
