  if (best && predicate(best[0], ["cryptographic", "delegation", "workload", "canary", "range"])) { vocab = "VERIFIED_IDENTITY"; operator = best[0]; basis = E.find((e) => e.type === "operator" && e.value === operator && e.strength === "verified").provenance; }
  else if (best && predicate(best[0], ["fcrdns"])) { vocab = "DNS_VERIFIED"; operator = best[0]; basis = "forward-confirmed reverse dns"; }
  else if (best && best[1] >= theta && (!second || best[1] - second[1] >= margin) && d.M[best[0]] <= eta && predicate(best[0], ["declaration"])) { vocab = "DECLARED_IDENTITY"; operator = best[0]; basis = "declaration token, unverified"; }
